import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val d = scanner.next()
    val n = d.length

    var dot = -1
    var e = -1
    for (i in 0 until n) {
        if (d[i] == '.') dot = i
        if (d[i] == 'e') {
            e = i
            break
        }
    }

    val expStr = d.substring(e + 1)
    val xb = expStr.toInt()

    val sb = StringBuilder()
    var stoppedEarly = false

    for (i in 0 until n) {
        if (d[i] == '.') {
            if (e - dot == 2 && d[dot + 1] == '0') {
                stoppedEarly = true
                break
            }
        } else if (d[i] == 'e') {
            break
        } else {
            if (i == dot + xb + 1) {
                sb.append('.')
            }
            sb.append(d[i])
        }
    }

    var zero = xb - (e - dot - 1)
    if (e - dot == 2 && d[dot + 1] == '0') {
        zero = xb
    }

    repeat(zero) { sb.append('0') }

    println(sb.toString())
}

